const s = msg.status || {};
let text = "disconnected";
if (s.fill === "green") { text = "connected"; }
else if (s.fill === "red") { text = s.text ? "error: " + s.text : "disconnected"; }
else if (s.text) { text = "mqtt: " + s.text; }
msg.payload = { chip: "mqtt", value: text };
return msg;

let payload;
try {
  if (typeof msg.payload === "string") { payload = JSON.parse(msg.payload); }
  else if (Buffer.isBuffer(msg.payload)) { payload = JSON.parse(msg.payload.toString("utf8")); }
  else { payload = msg.payload; }
} catch (e) {
  msg.payload = { error: "invalid-json", detail: e.message };
  return [null, msg];
}
if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
  msg.payload = { error: "not-an-object" };
  return [null, msg];
}
const required = ["timestamp", "approach", "vehicle_count", "queue_length", "avg_wait_time", "arrival_rate", "congestion_level", "scenario"];
const missing = required.filter(function (k) { return payload[k] === undefined || payload[k] === null || payload[k] === ""; });
if (missing.length) { msg.payload = { error: "missing-fields", missing: missing }; return [null, msg]; }
const approaches = ["North", "South", "East", "West"];
if (approaches.indexOf(payload.approach) === -1) { msg.payload = { error: "unknown-approach", approach: payload.approach }; return [null, msg]; }
const numeric = ["vehicle_count", "queue_length", "avg_wait_time", "arrival_rate"];
for (const k of numeric) {
  const n = Number(payload[k]);
  if (!isFinite(n) || n < 0) { msg.payload = { error: "invalid-number", field: k, value: payload[k] }; return [null, msg]; }
}
msg.payload = payload;
msg.approach = payload.approach;
msg.reading = payload;
return [msg, null];

const r = msg.reading;
msg.params = [
  r.timestamp,
  r.approach,
  Number(r.vehicle_count),
  Number(r.queue_length),
  Number(r.avg_wait_time),
  Number(r.arrival_rate),
  String(r.congestion_level).toUpperCase(),
  String(r.scenario),
  (r.sequence === undefined || r.sequence === null) ? null : Number(r.sequence)
];
return msg;

const r = msg.reading;
const boardMsg = RED.util.cloneMessage(msg);
boardMsg.topic = r.approach;
boardMsg.payload = r;
const chartMsg = RED.util.cloneMessage(msg);
chartMsg.topic = r.approach;
chartMsg.payload = Number(r.queue_length);
const chipMsg = RED.util.cloneMessage(msg);
chipMsg.topic = "strip";
chipMsg.payload = { chip: "data" };
return [boardMsg, chartMsg, chipMsg];

const err = msg.error || {};
const src = err.source || {};
msg.params = [
  "error",
  src.name || src.id || "flow",
  err.type || "uncaught-exception",
  err.message || String(err)
];
return msg;

let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); msg.payload = p; } catch (e) { return null; } }
if (!p || typeof p !== "object" || !p.signals) return null;
msg.topic = "signal";
const chip = RED.util.cloneMessage(msg);
chip.topic = "strip";
chip.payload = { chip: "controller", value: !p.running ? "standby" : (p.paused ? "paused" : "running") };
return [msg, chip];

let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== "object" || !p.command_id) return null;
if (p.state === "ALL_RED") msg.topic = "cmd";
else msg.topic = "cmd";
msg.payload = { cmd_id: p.command_id, approach: p.approach, state: p.state };
return msg;

let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== "object" || !p.command_id) return null;
msg.topic = "ack";
msg.payload = { chip: "ack", cmd_id: p.command_id, approach: p.approach,
                status: p.status, applied_state: p.applied_state, reason: p.reason || "" };
return msg;

let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) {} }
const t = msg.topic || "";
let out = null, key = null;
if (p && p.chip === "mqtt") { out = { type: "mqtt", data: p }; key = "mqtt"; }
else if (p && p.chip === "actuator") { out = { type: "health", data: p }; key = "health"; }
else if (t === "signal") { out = { type: "signal", data: p }; key = "signal"; }
else if (t === "cmd") { out = { type: "cmd", data: p }; }
else if (t === "ack") { out = { type: "ack", data: p }; }
else if (t === "team9/traffic/timing/decisions") { out = { type: "timing", data: p }; key = "timing"; }
else if (t === "team9/traffic/test/result") { out = { type: "test", data: p }; key = "test"; }
else if (p && p.approach && p.queue_length !== undefined) { out = { type: "reading", data: p }; key = "reading:" + p.approach; }
if (!out) { return null; }
if (key) { const c = flow.get("ws_cache") || {}; c[key] = out; flow.set("ws_cache", c); }
return { payload: out };

let p = msg.payload;
if (typeof p === "string") {
  try { p = JSON.parse(p); } catch (err) { return null; }
}
if (p && p.type === "hello") {
  const c = flow.get("ws_cache") || {};
  const replies = Object.keys(c).map(function (k) { return { payload: c[k], _session: msg._session }; });
  return [null, replies];
}
if (p && p.type === "publish" && p.payload && typeof p.payload === "object") {
  return [{ payload: JSON.stringify(p.payload) }, null];
}
return null;

// Derive ONE actuator-health value from the real heartbeat and the
// controller ack-timeout report. Both dashboards render this same value
// so they can never disagree about whether the actuator is alive.
var now = Date.now();
var p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) { p = null; } }
if (p && p.role === "actuator" && (p.status === "online" || p.status === "offline")) {
  flow.set("actuator_beat", p);
}
if (p && p.last_timeout) { flow.set("actuator_last_timeout", p.last_timeout); }
var beat = flow.get("actuator_beat");
var value = "waiting", cls = "", age = null, interval = 5;
if (beat) {
  interval = Number(beat.interval_seconds) || 5;
  var t = Date.parse(String(beat.timestamp).replace(" ", "T"));
  age = isNaN(t) ? Infinity : (now - t) / 1000;
  if (beat.status === "offline") { value = "stopped"; cls = "bad"; }
  else if (age <= interval * 2.5) { value = "healthy"; cls = "ok"; }
  else if (age <= interval * 5) { value = "stale"; cls = "warn"; }
  else { value = "disconnected"; cls = "bad"; }
}
if (value === "healthy") {
  var to = flow.get("actuator_last_timeout");
  if (to) {
    var tt = Date.parse(String(to.at).replace(" ", "T"));
    var tage = isNaN(tt) ? Infinity : (now - tt) / 1000;
    if (tage <= interval * 4) { value = "not responding"; cls = "warn"; }
  }
}
msg = { payload: { chip: "actuator", value: value, cls: cls,
  age_s: (age === null ? null : Math.round(age)), interval_s: interval } };
return msg;
